namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly object _lock = new();

    public List<Notification> GetInitialNotifications()
    {
        lock (_lock)
        {
            var notifications = new List<Notification>();
            for (int i = 0; i < 5; i++)
            {
                notifications.Add(new Notification(
                    _nextId++,
                    $"Welcome notification #{_nextId - 1}",
                    DateTime.UtcNow.AddMinutes(-10 + i)));
            }
            return notifications;
        }
    }

    public List<Notification> CheckForNewNotifications(int afterId)
    {
        lock (_lock)
        {
            // Simulate ~30% chance of a new notification arriving
            if (Random.Shared.Next(0, 10) < 3)
            {
                var id = _nextId++;
                return [new Notification(id, $"New alert #{id} — something happened!", DateTime.UtcNow)];
            }
            return [];
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private bool _isInteractive;

    protected override void OnInitialized()
    {
        // Runs during prerender AND when the component becomes interactive.
        // Load initial data only once (during prerender); the state persists
        // into the interactive runtime so we don't re-fetch.
        if (!_isInteractive)
        {
            notifications = NotificationService.GetInitialNotifications();
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during static SSR/prerender,
            // so reaching here means the component is now live & interactive.
            _isInteractive = true;
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            if (ct.IsCancellationRequested) break;

            var lastId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
            var newItems = NotificationService.CheckForNewNotifications(lastId);

            if (newItems.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications.AddRange(newItems);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

